<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { api, mutate, session } from '../../shared/api'
import { catalog, refreshCatalog, showError, toast } from '../../shared/state'
import type { Inventory, RoomType } from '../../shared/types'
import { addDays, money, shortDate } from '../../shared/format'
import Icon from '../../shared/Icon.vue'
import Modal from '../../shared/Modal.vue'
import Badge from '../../shared/Badge.vue'
const hotelId = computed(() => session.user?.hotelId || '')
const hotel = computed(() => catalog.value?.hotels.find(h => h.id === hotelId.value))
const roomTypes = computed(() => catalog.value?.roomTypes.filter(r => r.hotelId === hotelId.value) || [])
const from = ref(session.today), to = ref(addDays(session.today, 6)), room = ref(''), rows = ref<Inventory[]>([]), originals = ref<Inventory[]>([]), busy = ref(false), loading = ref(false)
const blocks = ref<{id: string; roomTypeId: string; startDate: string; endDate: string; quantity: number; reason: string; status: string}[]>([])
const visible = computed(() => rows.value.filter(r => !room.value || r.roomTypeId === room.value))
const changed = computed(() => rows.value.filter(r => { const old = originals.value.find(o => o.id === r.id); return old && (r.price !== old.price || r.quota !== old.quota) }))
const summary = computed(() => rows.value.reduce((s, r) => ({quota: s.quota + r.quota, occupied: s.occupied + r.occupied, blocked: s.blocked + r.blocked, available: s.available + r.available}), {quota: 0, occupied: 0, blocked: 0, available: 0}))
const modal = ref('')
const form = reactive({id: '', roomTypeId: '', startDate: session.today, endDate: addDays(session.today, 1), quantity: 1, reason: '', kind: 'MAINTENANCE', readyBeforeCheckin: false, code: '', name: '', capacity: 2, price: 300, quota: 10})
async function load() { loading.value = true; try { const data = await api<Inventory[]>(`/hotels/${hotelId.value}/daily-inventory?from=${from.value}&to=${to.value}`); rows.value = data; originals.value = JSON.parse(JSON.stringify(data)); blocks.value = await api(`/hotels/${hotelId.value}/blocks`) } catch (e) { showError(e) } finally { loading.value = false } }
onMounted(load)
async function save() { busy.value = true; try { const r = await mutate(`/hotels/${hotelId.value}/daily-inventory`, {entries: changed.value.map(x => ({id: x.id, version: x.version, price: x.price, quota: x.quota}))}, 'PUT'); toast(r.message); if (r.status === 'SUCCEEDED') await load() } catch (e) { showError(e) } finally { busy.value = false } }
function open(type: string) { modal.value = type; Object.assign(form, {id: '', roomTypeId: roomTypes.value[0]?.id || '', startDate: session.today, endDate: addDays(session.today, 1), quantity: 1, reason: '', kind: 'MAINTENANCE', readyBeforeCheckin: false, code: '', name: '', capacity: 2, price: 300, quota: 10}) }
function editRoom(type: RoomType) { open('room'); Object.assign(form, {id: type.id, code: type.code, name: type.name, capacity: type.capacity}) }
async function submit() { busy.value = true; try { const endpoint = modal.value === 'closure' ? 'closures' : modal.value === 'room' ? 'room-types' : 'blocks'; const r = await mutate(`/hotels/${hotelId.value}/${endpoint}`, form); toast(r.message); if (r.status === 'SUCCEEDED') { modal.value = ''; await refreshCatalog(); await load() } } catch (e) { showError(e) } finally { busy.value = false } }
async function blockAction(id: string, action: string) { busy.value = true; try { const r = await mutate(`/blocks/${id}/${action}`); toast(r.message); await load() } catch (e) { showError(e) } finally { busy.value = false } }
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">DAILY INVENTORY</span><h1>每日房源与价格</h1><p>{{ hotel?.name }} · 按住宿晚维护学校专用名额，已确认订单保留原锁定价。</p></div><div class="inline"><button class="button secondary" @click="open('room')"><Icon name="plus" :size="17"/>新增房型</button><button class="button danger-ghost" @click="open('closure')">登记酒店停业</button></div></div>
  <div class="metric-grid four"><div class="metric-card"><span>区间学校名额</span><strong>{{ summary.quota }}</strong><small>逐日汇总间夜</small></div><div class="metric-card"><span>已确认占用</span><strong>{{ summary.occupied }}</strong><small>与有效占用明细同步</small></div><div class="metric-card"><span>维修清洁停用</span><strong>{{ summary.blocked }}</strong><small>仅扣减实际停用晚</small></div><div class="metric-card accent"><span>区间可售间夜</span><strong>{{ summary.available }}</strong><small>停售晚不计入可售</small></div></div>
  <section class="card"><form class="filter-bar" @submit.prevent="load"><label>开始日期<input v-model="from" type="date" required/></label><label>结束日期<input v-model="to" type="date" :min="from" required/></label><label>房型<select v-model="room"><option value="">全部房型</option><option v-for="r in roomTypes" :key="r.id" :value="r.id">{{ r.name }}</option></select></label><button class="button secondary align-end" :disabled="loading">查询房源</button><button type="button" class="button secondary align-end" @click="open('block')">维修 / 清洁停用</button></form><div class="notice purple-notice"><Icon name="info" :size="18"/><span>学校名额不得低于已占用与停用数量之和。停业停售与占用独立管理，释放占用不会自动恢复销售。</span></div><div v-if="loading" class="empty-state">正在读取每日房源…</div><div v-else-if="!visible.length" class="empty-state">所选日期暂无逐日房源，可先新增房型。</div><div v-else class="table-wrap"><table class="inventory-table"><thead><tr><th>住宿晚</th><th>房型</th><th>当前单价 / 元</th><th>学校名额</th><th>已占用</th><th>停用扣减</th><th>可售</th><th>销售状态</th></tr></thead><tbody><tr v-for="r in visible" :key="r.id"><td>{{ shortDate(r.stayDate) }}</td><td>{{ r.roomName }}</td><td><input v-model.number="r.price" type="number" min="0" step="0.01" :aria-label="r.stayDate + r.roomName + '价格'"/></td><td><input v-model.number="r.quota" type="number" :min="r.occupied + r.blocked" :aria-label="r.stayDate + r.roomName + '学校名额'"/></td><td>{{ r.occupied }}</td><td>{{ r.blocked }}</td><td><strong :class="r.available > 0 ? 'green' : 'danger-text'">{{ r.available }}</strong></td><td><span class="badge" :class="r.stopSale ? 'badge-cancelled' : 'badge-checked_in'">{{ r.stopSale ? '停售' : '正常销售' }}</span></td></tr></tbody></table></div><div class="save-bar"><p class="muted">{{ changed.length ? `${changed.length} 条每日记录待保存` : '修改当前价格和名额后统一保存' }}</p><button class="button primary" :disabled="!changed.length || busy" @click="save">{{ busy ? '正在保存…' : '保存房源调整' }}</button></div></section>
  <section class="card gap-top"><div class="section-heading"><h2>停用区间与冲突跟进</h2><span class="muted small">恢复日当晚不扣减</span></div><div v-if="!blocks.length" class="subtle-empty">暂无维修或清洁停用记录。</div><div v-else class="table-wrap"><table><thead><tr><th>房型 / 原因</th><th>停用日期</th><th>数量</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="b in blocks" :key="b.id"><td>{{ roomTypes.find(r => r.id === b.roomTypeId)?.name }}<small class="cell-sub">{{ b.reason }}</small></td><td>{{ shortDate(b.startDate) }} — {{ shortDate(b.endDate) }}</td><td>{{ b.quantity }}</td><td><Badge :status="b.status"/></td><td><button v-if="b.status === 'PENDING'" class="text-button" :disabled="busy" @click="blockAction(b.id, 'apply')">协调后重试</button><button v-if="b.status === 'APPLIED'" class="text-button" :disabled="busy" @click="blockAction(b.id, 'release')">解除本次停用</button></td></tr></tbody></table></div></section>
  <Modal v-if="modal" :title="modal === 'closure' ? '登记酒店停业范围' : modal === 'room' ? '维护本酒店房型' : '登记维修或清洁停用'" @close="modal = ''"><form id="inventory-form" class="form-stack" @submit.prevent="submit"><template v-if="modal === 'room'"><div class="form-grid two"><label>房型代码<input v-model="form.code" required pattern="[A-Za-z0-9_]+" maxlength="32" placeholder="如 DOUBLE、SINGLE"/></label><label>房型名称<input v-model="form.name" required maxlength="80" placeholder="如 舒适双床房"/></label><label>每间可住人数<input v-model.number="form.capacity" type="number" min="1" max="20" required/></label><label>初始每日单价<input v-model.number="form.price" type="number" min="0" step="0.01" required/></label><label>初始每日学校名额<input v-model.number="form.quota" type="number" min="0" required/></label></div><p class="muted">将建立未来180天的初始每日记录，后续可逐日调整。</p></template><template v-else><div v-if="modal === 'closure'" class="notice warning">确认后立即停售受影响日期，将相关已确认及已入住订单转待安置并保留原占用。已入住订单请先核实和记录已住间夜。</div><template v-if="modal === 'block'"><label>房型<select v-model="form.roomTypeId" required><option v-for="r in roomTypes" :key="r.id" :value="r.id">{{ r.name }}</option></select></label><label>停用类型<select v-model="form.kind"><option value="MAINTENANCE">维修</option><option value="CLEANING">清洁</option></select></label></template><div class="form-grid two"><label>停用 / 停业开始日<input v-model="form.startDate" type="date" required/></label><label>恢复日期（当晚恢复）<input v-model="form.endDate" type="date" :min="addDays(form.startDate, 1)" required/></label></div><label v-if="modal === 'block'">每晚停用间数<input v-model.number="form.quantity" type="number" min="1" required/></label><label v-if="modal === 'block' && form.kind === 'CLEANING'" class="check-line"><input v-model="form.readyBeforeCheckin" type="checkbox"/>清洁可在当晚入住前完成，不扣当晚名额</label><label>原因与说明<textarea v-model="form.reason" required maxlength="500"/></label></template></form><template #footer><button class="button secondary" @click="modal = ''">返回</button><button form="inventory-form" class="button" :class="modal === 'closure' ? 'danger' : 'primary'" :disabled="busy">{{ busy ? '正在提交…' : modal === 'closure' ? '确认停业并生成安置记录' : '确认保存' }}</button></template></Modal>
  <section class="card gap-top"><div class="section-heading"><h2>本酒店房型档案</h2><span class="muted small">名称与容量维护</span></div><div v-for="type in roomTypes" :key="type.id" class="detail-row"><div><strong>{{ type.name }}</strong><small class="cell-sub">{{ type.code }} · 每间可住 {{ type.capacity }} 人</small></div><button class="text-button" @click="editRoom(type)">维护房型</button></div></section>
</template>
